mapper.select:
SELECT  sap.*,
    p.id                    'project.id',
    p.short_name            'project.shortName',
    p.serial_number         'project.serialNumber',
    p.name                  'project.name',
    ap.approve_info_name approveInfoName
FROM scm_apply_purchase sap
left join contract_project p on p.id = sap.project_id
left join approve_process ap on ap.id = sap.approve_process_id
WHERE sap.bool_delete_enum = 0
  and sap.bool_initiate_approve = #{boolInitiateApprove}

    and sap.material_type = #{materialType}


    and sap.review_status = #{status}


    and sap.serial_number like CONCAT('%', #{serialNumber},'%')


    and sap.enabled = #{enabled}


    
        and sap.create_time > #{times[0]}
    
    
        and sap.create_time < #{times[1]}

SELECT  sap.*
FROM scm_apply_purchase sap
WHERE sap.bool_delete_enum = 0
  and bool_temporary_storage = 0
  and data_status in (1,2,3)

    and (sap.material_type = #{materialType} or #{materialType} & sap.material_type)


    and sap.data_status = #{status}


    and sap.serial_number like CONCAT('%', #{serialNumber},'%')


    and sap.enabled = #{enabled}


    
        and sap.create_time > #{times[0]}
    
    
        and sap.create_time < #{times[1]}
    


and sap.department_name like CONCAT('%', #{departmentName},'%')


and sap.applicant_name like CONCAT('%', #{applicantName},'%')


    AND find_in_set(#{projectId}, sap.project_ids)


    AND sap.project_attribute = #{projectAttribute}


    AND sap.purchase_creation_state = #{purchaseCreationState}


    AND sap.level = #{level}


    AND sap.branch_company_id = #{branchCompanyId}

        select sap.*
        FROM scm_apply_purchase sap
        
            bool_delete_enum = 0 and enabled = 1
            and data_status = 2
            
                
                    and sap.create_time > #{times[0]}
                
                
                    and sap.create_time < #{times[1]}
                
            
            
                and #{materialType} & sap.material_type
            
            
                and purchase_creation_state = #{purchaseCreationState}
            
            
                and sap.level = #{level}
            
            
                and (find_in_set(#{projectAttribute},sap.project_attribute) or sap.project_attribute is NUll or sap.project_attribute = '')
            
            
                and sap.branch_company_id = #{branchCompanyId}
            
            
                and FIND_IN_SET(#{projectId}, project_ids)
